import { Component, ViewEncapsulation, inject } from '@angular/core';
import { RouterLink } from '@angular/router';
import { AsyncPipe } from '@angular/common';
import { LocalizationPipe } from '@abp/ng.core';
import {
  IconComponent,
  LpxNavbarItem,
  UserProfileService,
} from '@volo/ngx-lepton-x.core';

@Component({
  selector: 'lpx-mn-user-profile',
  templateUrl: './mn-user-profile.component.html',
  encapsulation: ViewEncapsulation.None,
  imports: [IconComponent, RouterLink, AsyncPipe, LocalizationPipe],
})
export class MnUserProfileComponent {
  private service = inject(UserProfileService);
  user$ = this.service.user$;
  menuHidden = true;

  toggleMenu() {
    this.menuHidden = !this.menuHidden;
  }

  onActionClick(item: LpxNavbarItem) {
    item.action?.();
  }
}
