import { Component, ContentChild, OnDestroy, inject } from '@angular/core';
import { NgTemplateOutlet, AsyncPipe } from '@angular/common';
import {
  NavbarService,
  LayoutService,
  LogoPanelDirective,
  IconComponent,
  BrandLogoComponent,
  NavbarRoutesComponent,
} from '@volo/ngx-lepton-x.core';

@Component({
  selector: 'lpx-mobile-navbar',
  templateUrl: './mobile-navbar.component.html',
  styles: [
    `
      .mobile-menu-opened :host {
        height: 100vh;
        display: block;
      }
    `,
  ],
  imports: [
    NgTemplateOutlet,
    IconComponent,
    NavbarRoutesComponent,
    BrandLogoComponent,
    AsyncPipe,
  ],
})
export class MobileNavbarComponent implements OnDestroy {
  navService = inject(NavbarService);
  private layoutService = inject(LayoutService);

  userMenuHidden = true;
  navItemsHidden = true;
  mobileMenuOpened = 'mobile-menu-opened';

  @ContentChild(LogoPanelDirective) logoPanel?: LogoPanelDirective;

  ngOnDestroy() {
    this.layoutService.removeClass(this.mobileMenuOpened);
  }

  toggleUserMenu() {
    this.userMenuHidden = !this.userMenuHidden;
    if (!this.userMenuHidden) {
      this.navItemsHidden = true;
      this.setLayoutClass();
    }
  }

  toggleNavbar() {
    this.navItemsHidden = !this.navItemsHidden;
    if (!this.navItemsHidden) {
      this.userMenuHidden = true;
    }
    this.setLayoutClass();
  }

  setLayoutClass() {
    if (this.navItemsHidden) {
      this.layoutService.removeClass(this.mobileMenuOpened);
    } else {
      this.layoutService.addClass(this.mobileMenuOpened);
    }
  }
}
