import {
  EnvironmentProviders,
  makeEnvironmentProviders,
  Provider,
} from '@angular/core';
import { HasStyleFactory } from '@volo/ngx-lepton-x.core';
import { getSideMenuLayoutStylesProvider } from './style.provider';

export type LpxSideMenuLayoutOptions = HasStyleFactory;

export enum LpxSideMenuLayoutFeatureKind {
  Options,
  AppendDefaults,
}

export interface LpxSideMenuLayoutFeature<
  KindT extends LpxSideMenuLayoutFeatureKind,
> {
  ɵkind: KindT;
  ɵproviders: (Provider | EnvironmentProviders)[];
}

function makeLpxSideMenuLayoutFeature<
  KindT extends LpxSideMenuLayoutFeatureKind,
>(
  kind: KindT,
  providers: (Provider | EnvironmentProviders)[],
): LpxSideMenuLayoutFeature<KindT> {
  return {
    ɵkind: kind,
    ɵproviders: providers,
  };
}

export function withLpxSideMenuOptions(
  options = {} as LpxSideMenuLayoutOptions,
): LpxSideMenuLayoutFeature<LpxSideMenuLayoutFeatureKind.Options> {
  return makeLpxSideMenuLayoutFeature(LpxSideMenuLayoutFeatureKind.Options, [
    getSideMenuLayoutStylesProvider(options.styleFactory),
  ]);
}

export const APPEND_DEFAULTS: LpxSideMenuLayoutFeature<LpxSideMenuLayoutFeatureKind.AppendDefaults> =
  makeLpxSideMenuLayoutFeature(LpxSideMenuLayoutFeatureKind.AppendDefaults, [
    getSideMenuLayoutStylesProvider(),
  ]);

export function provideLpxSideMenuLayout(
  ...features: LpxSideMenuLayoutFeature<LpxSideMenuLayoutFeatureKind>[]
): EnvironmentProviders {
  const providers: (Provider | EnvironmentProviders)[] = [];
  features.forEach(({ ɵproviders }) => providers.push(...ɵproviders));

  return makeEnvironmentProviders(providers);
}
